INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation)
VALUES
('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] หน้าที่ของส่วนต่างๆ ของพืช: รากและลำต้น', 'easy', 'mcq', 'ส่วนใดของพืชทำหน้าที่ดูดน้ำและแร่ธาตุจากดินขึ้นไปเลี้ยงส่วนต่างๆ?', '["ใบ","ดอก","ราก","ผล"]'::jsonb, 2, 'รากทำหน้าที่ยึดลำต้นให้ติดกับดิน และดูดน้ำกับแร่ธาตุขึ้นไปส่งต่อให้ลำต้น'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] ท่อลำเลียงน้ำและท่อลำเลียงอาหาร', 'medium', 'mcq', 'ท่อลำเลียงน้ำ (ไซเลม) และท่อลำเลียงอาหาร (โฟลเอ็ม) ในลำต้นพืช มีทิศทางการลำเลียงอย่างไร?', '["ท่อลำเลียงน้ำลำเลียงจากรากขึ้นสู่ใบ ท่อลำเลียงอาหารลำเลียงจากใบไปส่วนต่างๆ","ท่อลำเลียงน้ำลำเลียงจากใบคงลงสู่รากเท่านั้น","ทั้งสองท่อลำเลียงจากดินขึ้นสู่ยอดพร้อมกัน","ท่อลำเลียงอาหารลำเลียงจากรากขึ้นสู่ดอก"]'::jsonb, 0, 'ท่อลำเลียงน้ำดูดน้ำจากรากขึ้นสู่ใบ ส่วนท่อลำเลียงอาหารลำเลียงน้ำตาลที่สร้างจากใบไปเลี้ยงส่วนต่างๆ ของพืช'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] หน้าที่ของใบและการสังเคราะห์ด้วยแสง', 'easy', 'mcq', 'ปัจจัยสำคัญที่พืชใช้ในกระบวนการสังเคราะห์ด้วยแสงคือข้อใด?', '["แสงแดด, คลอโรฟิลล์, น้ำ, แก๊สคาร์บอนไดออกไซด์","แสงแดด, ดิน, น้ำมัน, แก๊สออกซิเจน","ความมืด, ปุ๋ย, แก๊สไนโตรเจน","น้ำตาล, เกลือ, น้ำ, แก๊สคาร์บอนไดออกไซด์"]'::jsonb, 0, 'พืชใช้คลอโรฟิลล์ดูดกลืนพลังงานแสง รวมกับน้ำและแก๊สคาร์บอนไดออกไซด์ เพื่อสร้างน้ำตาลและแก๊สออกซิเจน'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] ผลผลิตจากการสังเคราะห์ด้วยแสง', 'easy', 'mcq', 'แก๊สชนิดใดที่พืชคายออกมาจากกระบวนการสังเคราะห์ด้วยแสง ซึ่งเป็นประโยชน์ต่อการหายใจของสัตว์และมนุษย์?', '["แก๊สคาร์บอนมอนอกไซด์","แก๊สออกซิเจน","แก๊สคาร์บอนไดออกไซด์","แก๊สไฮโดรเจน"]'::jsonb, 1, 'ผลผลิตจากการสังเคราะห์ด้วยแสงคือน้ำตาลกลูโคสและแก๊สออกซิเจน ซึ่งสิ่งมีชีวิตใช้ในการหายใจ'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] การคายน้ำของพืช', 'medium', 'mcq', 'พืชคายน้ำออกทางโครงสร้างใดเป็นหลัก?', '["ขนราก","ปากใบ (Stomata)","กลีบดอก","เปลือกลำต้น"]'::jsonb, 1, 'พืชคายน้ำในรูปของไอน้ำออกทางปากใบที่อยู่บริเวณใต้ใบเป็นส่วนใหญ่'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] การจำแนกพืชดอกและพืชไม่มีดอก', 'easy', 'mcq', 'พืชในข้อใดจัดเป็น "พืชไม่มีดอก"?', '["กุหลาบ, ชบา","ทานตะวัน, กล้วยไม้","เฟิร์น, มอส","มะม่วง, มะลิ"]'::jsonb, 2, 'เฟิร์นและมอสเป็นพืชไม่มีดอก โดยสืบพันธุ์โดยการสร้างสปอร์'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] ลักษณะของพืชใบเลี้ยงเดี่ยว', 'medium', 'mcq', 'ข้อใดเป็นลักษณะเฉพาะของ "พืชใบเลี้ยงเดี่ยว"?', '["เส้นใบเป็นร่างแห, ระบบรากแก้ว","เส้นใบขนาน, ระบบรากฝอย, มีใบเลี้ยง 1 ใบ","ลำต้นไม่มีข้อปล้อง, กลีบดอกมี 4-5 กลีบ","มีเนื้อไม้ขนาดใหญ่ ไม่มีข้อปล้อง"]'::jsonb, 1, 'พืชใบเลี้ยงเดี่ยว เช่น ข้าว ข้าวโพด มะพร้าว มีใบเลี้ยง 1 ใบ เส้นใบเรียงขนาน และมีระบบรากฝอย'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] ลักษณะของพืชใบเลี้ยงคู่', 'medium', 'mcq', 'พืชในข้อใดจัดเป็น "พืชใบเลี้ยงคู่" ทั้งหมด?', '["ข้าว, ข้าวโพด, หญ้า","มะม่วง, ถั่วเขียว, กุหลาบ","ไผ่, มะพร้าว, อ้อย","กล้วย, หญ้าแพรก, ข่า"]'::jsonb, 1, 'มะม่วง ถั่วเขียว กุหลาบ มีเส้นใบเป็นร่างแห ระบบรากแก้ว และมีใบเลี้ยง 2 ใบ จึงเป็นพืชใบเลี้ยงคู่'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] ส่วนประกอบของดอกไม้', 'easy', 'mcq', 'ส่วนประกอบของดอกไม้ที่มีสีสันสวยงามและมีกลิ่นหอมเพื่อล่อแมลงคือส่วนใด?', '["กลีบเลี้ยง","กลีบดอก","เกสรเพศผู้","เกสรเพศเมีย"]'::jsonb, 1, 'กลีบดอกมีหน้าที่ดึงดูดแมลงให้มาช่วยผสมเกสรด้วยสีสันและกลิ่นหอม'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] การทดสอบแป้งในใบพืช', 'hard', 'mcq', 'สารละลายใดที่ใช้ทดสอบหาแป้งที่พืชสะสมไว้ โดยจะเปลี่ยนเป็นสีน้ำเงินเข้มหรือสีน้ำเงินแกมม่วง?', '["สารละลายเบเนดิกต์","สารละลายไอโอดีน","แอลกอฮอล์บริสุทธิ์","น้ำเกลือ"]'::jsonb, 1, 'สารละลายไอโอดีนจะทำปฏิกิริยากับแป้งแล้วเปลี่ยนจากสีน้ำตาลอมส้มเป็นสีน้ำเงินเข้มหรือม่วงเข้ม'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] การจำแนกสัตว์: สัตว์มีกระดูกสันหลัง', 'easy', 'mcq', 'สัตว์ในข้อใดจัดเป็นสัตว์มีกระดูกสันหลังทั้งหมด?', '["ปลา, สุนัข, กบ, นก","แมงกะพรุน, ดาวทะเล, ปลาหมึก","หอย, กุ้ง, ปู, ไส้เดือน","พยาธิ, แมลงวัน, ยุง, ผึ้ง"]'::jsonb, 0, 'ปลา สุนัข กบ นก มีกระดูกแกนกลางพยุงร่างกาย จัดเป็นสัตว์มีกระดูกสันหลัง'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] กลุ่มปลา', 'easy', 'mcq', 'ปลาหายใจด้วยอวัยวะใด และออกลูกอย่างไรเป็นส่วนใหญ่?', '["หายใจด้วยปอด, ออกลูกเป็นตัว","หายใจด้วยเหงือก, ออกลูกเป็นไข่","หายใจด้วยผิวหนัง, ออกลูกเป็นตัว","หายใจด้วยเหงือก, ออกลูกเป็นตัว"]'::jsonb, 1, 'ปลาอาศัยในน้ำ ใช้เหงือกในการแลกเปลี่ยนแก๊ส และส่วนใหญ่ออกลูกเป็นไข่ (เป็นสัตว์เลือดเย็น)'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] กลุ่มสัตว์สะเทินน้ำสะเทินบก', 'medium', 'mcq', 'สัตว์กลุ่มสะเทินน้ำสะเทินบก (เช่น กบ คางคก) ในวัยตัวอ่อน (ลูกอ๊อด) หายใจด้วยอวัยวะใด?', '["ปอด","เหงือก","ผิวหนังและปอด","จมูก"]'::jsonb, 1, 'วัยลูกอ๊อดอาศัยอยู่ในน้ำและหายใจด้วยเหงือก เมื่อโตเต็มวัยขึ้นมาอยู่บนบกจะหายใจด้วยปอดและผิวหนัง'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] กลุ่มสัตว์เลื้อยคลาน', 'medium', 'mcq', 'ข้อใดเป็นลักษณะสำคัญของ "สัตว์เลื้อยคลาน"?', '["ผิวหนังเปียกชื้น ไม่มีเกล็ด","ผิวหนังแห้ง มีเกล็ดปกคลุม หายใจด้วยปอด","มีขนเป็นแผง มีปีกบินได้","มีต่อมน้ำนมเลี้ยงลูก"]'::jsonb, 1, 'สัตว์เลื้อยคลาน เช่น จระเข้ เต่า งู กิ้งก่า ผิวหนังแห้งมีเกล็ดแข็งปกคลุม วางไข่บนบก และหายใจด้วยปอด'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] กลุ่มสัตว์ปีก', 'easy', 'mcq', 'สัตว์กลุ่มใดจัดเป็นสัตว์เลือดอุ่นและมีกระดูกกลวงเบาช่วยในการบิน?', '["สัตว์เลื้อยคลาน","สัตว์สะเทินน้ำสะเทินบก","สัตว์ปีก","ปลา"]'::jsonb, 2, 'สัตว์ปีก (นก เป็ด ไก่) เป็นสัตว์เลือดอุ่น มีขนเป็นแผง และกระดูกกลวงเบาเพื่อช่วยลดน้ำหนักในการบิน'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] กลุ่มสัตว์เลี้ยงลูกด้วยน้ำนม', 'easy', 'mcq', 'สัตว์น้ำในข้อใดจัดเป็น "สัตว์เลี้ยงลูกด้วยน้ำนม" ไม่ใช่ปลา?', '["ฉลาม","ปลากระเบน","วาฬและโลมา","ปลาทู"]'::jsonb, 2, 'วาฬและโลมาหายใจด้วยปอด เลี้ยงลูกด้วยน้ำนม ออกลูกเป็นตัว จัดเป็นสัตว์เลี้ยงลูกด้วยน้ำนม'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] สัตว์เลี้ยงลูกด้วยน้ำนมที่บินได้', 'medium', 'mcq', 'สัตว์ในข้อใดจัดเป็นสัตว์เลี้ยงลูกด้วยน้ำนมที่สามารถบินได้?', '["ค้างคาว","กระรอกบิน","นกเพนกวิน","นกกระจอกเทศ"]'::jsonb, 0, 'ค้างคาวมีต่อมน้ำนม ออกลูกเป็นตัว และเป็นสัตว์เลี้ยงลูกด้วยน้ำนมเพียงชนิดเดียวที่บินได้จริง'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] สัตว์ไม่มีกระดูกสันหลัง: กลุ่มขาข้อ', 'medium', 'mcq', 'สัตว์ที่มีขาเป็นข้อและมี 6 ขา จัดเป็นสัตว์จำพวกใด?', '["แมง (เช่น แมงมุม)","แมลง (เช่น ผึ้ง ตั๊กแตน)","สัตว์พวกกุ้งกั้งปู","กิ้งกือ"]'::jsonb, 1, 'แมลงมี 6 ขา ลำตัวแบ่งเป็น 3 ส่วน (หัว อก ท้อง) ส่วนแมงมุมมี 8 ขา'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] สัตว์ไม่มีกระดูกสันหลัง: หอยและหมึก', 'easy', 'mcq', 'สัตว์ในข้อใดเป็นสัตว์ไม่มีกระดูกสันหลังที่มีลำตัวนิ่ม?', '["ปลาทอง","หมึกกล้วย","กบหนอง","จิ้งจก"]'::jsonb, 1, 'หมึกกล้วยและหอยเป็นสัตว์ไม่มีกระดูกสันหลังจำพวกลำตัวนิ่ม'),
('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] สัตว์เลือดอุ่นและสัตว์เลือดเย็น', 'hard', 'mcq', 'สัตว์กลุ่มใดจัดเป็น "สัตว์เลือดเย็น" (อุณหภูมิร่างกายเปลี่ยนตามสภาพแวดล้อม)?', '["นกและสัตว์เลี้ยงลูกด้วยน้ำนม","ปลา สัตว์สะเทินน้ำสะเทินบก และสัตว์เลื้อยคลาน","มนุษย์และสุนัข","วาฬและลิง"]'::jsonb, 1, 'ปลา สัตว์สะเทินน้ำสะเทินบก และสัตว์เลื้อยคลาน เป็นสัตว์เลือดเย็น อุณหภูมิร่างกายปรับเปลี่ยนตามสิ่งแวดล้อม'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/1] สมบัติความแข็งของวัสดุ', 'easy', 'mcq', 'เมื่อนำวัตถุ A มาขูดบนวัตถุ B แล้วพบว่าวัตถุ B เกิดรอย แสดงว่าสมบัติความแข็งของวัตถุทั้งสองเป็นอย่างไร?', '["วัตถุ B แข็งกว่าวัตถุ A","วัตถุ A แข็งกว่าวัตถุ B","วัตถุทั้งสองแข็งเท่ากัน","ไม่สามารถสรุปได้"]'::jsonb, 1, 'วัตถุที่มีความแข็งมากกว่าเมื่อนำไปขูดขีดวัตถุอื่น จะทำให้วัตถุที่แข็งน้อยกว่าเกิดรอย'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/1] สภาพยืดหยุ่นของวัสดุ', 'easy', 'mcq', 'วัสดุในข้อใดมี "สภาพยืดหยุ่น" ดีที่สุด?', '["ดินน้ำมัน","ยางรัดของ","แท่งแก้ว","แผ่นไม้"]'::jsonb, 1, 'ยางรัดของเมื่อถูกดึงยืดออกแล้วปล่อย จะสามารถกลับคืนสู่สภาพเดิมได้ จึงมีสภาพยืดหยุ่นสูง'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/1] การนำความร้อนของวัสดุ', 'medium', 'mcq', 'วัสดุใดนำความร้อนได้ดีที่สุด จึงนิยมนำมาทำก้นกระทะและหม้อหุงต้ม?', '["ไม้","พลาสติก","โลหะ (เช่น อะลูมิเนียม สแตนเลส)","แก้ว"]'::jsonb, 2, 'โลหะเป็นตัวนำความร้อนที่ดี ทำให้อาหารได้รับความร้อนและสุกเร็ว ส่วนด้ามจับมักทำจากฉนวนความร้อน เช่น พลาสติกหรือไม้'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/1] การนำไฟฟ้าของวัสดุ', 'easy', 'mcq', 'วัตถุที่ยอมให้กระแสไฟฟ้าไหลผ่านได้ เรียกว่าอะไร?', '["ฉนวนไฟฟ้า","ตัวนำไฟฟ้า","สารกึ่งตัวนำ","แม่เหล็ก"]'::jsonb, 1, 'ตัวนำไฟฟ้า คือวัตถุที่ยอมให้กระแสไฟฟ้าไหลผ่านได้ เช่น ทองแดง อะลูมิเนียม เงิน เหล็ก'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/1] ฉนวนไฟฟ้า', 'easy', 'mcq', 'วัสดุใดนิยมใช้หุ้มสายไฟเพื่อป้องกันไฟฟ้ารั่วและไฟดูด?', '["ทองแดง","เหล็ก","พลาสติกหรือยาง","อะลูมิเนียม"]'::jsonb, 2, 'พลาสติกและยางเป็นฉนวนไฟฟ้า ไม่ยอมให้กระแสไฟฟ้าไหลผ่าน จึงปลอดภัยเมื่อสัมผัส'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/3] สมบัติของของแข็ง', 'easy', 'mcq', 'ข้อใดเป็นสมบัติที่ถูกต้องของสารในสถานะ "ของแข็ง"?', '["มีมวล รูปร่างและปริมาตรคงที่ ไม่เปลี่ยนตามภาชนะ","รูปร่างเปลี่ยนตามภาชนะ แต่ปริมาตรคงที่","ฟุ้งกระจายเต็มภาชนะเสมอ","ไม่มีมวลและไม่ต้องการที่อยู่"]'::jsonb, 0, 'ของแข็งมีอนุภาคเรียงชิดติดกันแน่น ทำให้มีมวล มีรูปร่างและปริมาตรที่คงที่แน่นอน'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/3] สมบัติของของเหลว', 'medium', 'mcq', 'เมื่อเทน้ำ 100 มิลลิลิตร จากแก้วทรงกระบอกลงในจานแบน สิ่งใดจะเปลี่ยนแปลงไป และสิ่งใดคงเดิม?', '["รูปร่างเปลี่ยนไปตามจาน แต่ปริมาตรคงเดิม 100 มิลลิลิตร","ทั้งรูปร่างและปริมาตรเปลี่ยนไปทั้งหมด","รูปร่างคงเดิม แต่ปริมาตรลดลง","ไม่มีสิ่งใดเปลี่ยนแปลง"]'::jsonb, 0, 'ของเหลวมีปริมาตรคงที่ แต่อนุภาคเลื่อนไหลได้ รูปร่างจึงเปลี่ยนไปตามภาชนะที่บรรจุ'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/3] สมบัติของแก๊ส', 'medium', 'mcq', 'ข้อใดเป็นสมบัติเด่นของสารในสถานะ "แก๊ส"?', '["มีรูปร่างแน่นอน","อนุภาคอยู่ห่างกันมาก ฟุ้งกระจายเต็มภาชนะ และอัดให้เล็กลงได้","ปริมาตรคงที่เสมอ","ไม่สามารถชั่งหามวลได้"]'::jsonb, 1, 'แก๊สมีอนุภาคอยู่ห่างกันมาก เคลื่อนที่อิสระ จึงฟุ้งกระจายเต็มภาชนะและสามารถถูกบีบอัดปริมาตรได้'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/4] การหาปริมาตรของของแข็งที่มีรูปทรงไม่แน่นอน', 'hard', 'mcq', 'การหาปริมาตรของก้อนหินที่มีรูปร่างไม่แน่นอน นิยมใช้วิธีการใด?', '["ใช้ไม้บรรทัดวัดความกว้าง ยาว สูง","การแทนที่น้ำโดยใช้ถ้วยยูเรกาและกระบอกตวง","ใช้เครื่องชั่งดิจิทัล","นำไปต้มจนละลาย"]'::jsonb, 1, 'ใช้วิธีการแทนที่น้ำ ปริมาตรของน้ำที่ล้นออกมาจากถ้วยยูเรกาจะเท่ากับปริมาตรของก้อนหิน'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/4] การพิสูจน์ว่าอากาศมีมวล', 'medium', 'mcq', 'การทดลองใดสามารถพิสูจน์ได้ว่า "อากาศมีมวล"?', '["เปรียบเทียบน้ำหนักของลูกโป่งที่สูบลมเต็มกับลูกโป่งที่แฟบ บนคานไม้แขวน","นำลูกโป่งไปลอยน้ำ","เปิดพัดลมเป่าลูกโป่ง","นำลูกโป่งไปตากแดด"]'::jsonb, 0, 'ลูกโป่งที่สูบลมจะหนักกว่าลูกโป่งที่แฟบ ทำให้คานเอียงไปข้างที่สูบลม พิสูจน์ว่าอากาศมีมวล'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/1] แรงโน้มถ่วงของโลก', 'easy', 'mcq', 'ผลไม้สุกที่หลุดจากขั้วจะตกลงสู่พื้นดินเสมอ เกิดจากแรงชนิดใด?', '["แรงเสียดทาน","แรงแม่เหล็ก","แรงโน้มถ่วงของโลก","แรงผลักของลม"]'::jsonb, 2, 'แรงโน้มถ่วงของโลกเป็นแรงดึงดูดที่โลกกระทำต่อมวลของวัตถุทุกชนิด โดยดึงดูดเข้าสู่ศูนย์กลางของโลก'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/1] ประโยชน์ของแรงโน้มถ่วง', 'easy', 'mcq', 'ข้อใดเป็นประโยชน์ที่เกิดจาก "แรงโน้มถ่วงของโลก"?', '["ทำให้มนุษย์และสิ่งของไม่ลอยเคว้งคว้างในอากาศ","ทำให้เรายกของหนักได้ง่ายขึ้น","ทำให้ฝนตกย้อนขึ้นสู่ก้อนเมฆ","ทำให้รถยนต์วิ่งเร็วขึ้น"]'::jsonb, 0, 'แรงโน้มถ่วงช่วยยึดเหนี่ยวสิ่งมีชีวิต บรรยากาศ และสิ่งของต่างๆ ให้อยู่บนพื้นผิวโลกได้'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/2] ความแตกต่างระหว่างมวลและน้ำหนัก', 'medium', 'mcq', 'ข้อใดอธิบายความแตกต่างระหว่าง "มวล" และ "น้ำหนัก" ได้ถูกต้อง?', '["มวลมีหน่วยเป็นนิวตัน ส่วนน้ำหนักมีหน่วยเป็นกิโลกรัม","มวลคือปริมาณเนื้อสารมีค่าคงที่ แต่น้ำหนักคือแรงดึงดูดของโลกมีหน่วยเป็นนิวตัน","ทั้งมวลและน้ำหนักจะเปลี่ยนไปเมื่อไปอยู่ที่ดวงจันทร์","มวลขึ้นอยู่กับแรงโน้มถ่วง แต่น้ำหนักไม่ขึ้นอยู่กับแรงโน้มถ่วง"]'::jsonb, 1, 'มวล (Mass) คือเนื้อของสาร มีค่าคงที่ทุกที่ (หน่วย kg) ส่วนน้ำหนัก (Weight) คือแรงโน้มถ่วงที่กระทำต่อมวล (หน่วย นิวตัน)'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/2] น้ำหนักของวัตถุบนดวงจันทร์', 'hard', 'mcq', 'หากนำวัตถุหนัก 60 นิวตันบนโลก ไปชั่งบนดวงจันทร์ วัตถุนี้จะมีน้ำหนักประมาณเท่าใด? (ดวงจันทร์มีแรงโน้มถ่วง 1/6 ของโลก)', '["60 นิวตัน","10 นิวตัน","360 นิวตัน","0 นิวตัน"]'::jsonb, 1, 'แรงโน้มถ่วงของดวงจันทร์มีเพียง 1/6 ของโลก ดังนั้นน้ำหนักจะเหลือ 60 ÷ 6 = 10 นิวตัน'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/3] เครื่องมือวัดแรงหรือน้ำหนัก', 'easy', 'mcq', 'เครื่องมือใดใช้สำหรับวัดแรงหรือน้ำหนักของวัตถุ โดยมีหน่วยเป็นนิวตัน?', '["ไม้บรรทัด","เครื่องชั่งสปริง","เทอร์โมมิเตอร์","กระบอกตวง"]'::jsonb, 1, 'เครื่องชั่งสปริงใช้สปริงที่ยืดออกตามแรงดึงดูดเพื่อวัดน้ำหนักของวัตถุในหน่วยนิวตัน'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/1] ข้อจำกัดของแรงโน้มถ่วง', 'medium', 'mcq', 'กิจกรรมใดเป็นกิจกรรมที่ต้อง "ออกแรงต้าน" แรงโน้มถ่วงของโลก?', '["การกระโดดร่มลงสู่พื้น","การปีนหน้าผาขึ้นสู่ยอดเขา","การเดินลงบันได","การปล่อยลูกบอลให้ตก"]'::jsonb, 1, 'การปีนเขาหรือยกของขึ้นที่สูงเป็นการเคลื่อนที่สวนทางกับทิศทางของแรงโน้มถ่วง จึงต้องออกแรงต้าน'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] การเคลื่อนที่ของแสง', 'easy', 'mcq', 'แสงเดินทางออกจากแหล่งกำเนิดแสงในลักษณะใด?', '["เดินทางเป็นเส้นตรงในทุกทิศทาง","เดินทางเป็นคลื่นโค้งไปมา","เดินทางเฉพาะแนวตั้งเท่านั้น","เดินทางเฉพาะเมื่อมีตัวกลางของแข็ง"]'::jsonb, 0, 'แสงเดินทางเป็นเส้นตรงออกจากแหล่งกำเนิดแสงทุกทิศทางด้วยความเร็วสูงมาก'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] ตัวกลางโปร่งใส', 'easy', 'mcq', 'วัตถุที่ยอมให้แสงผ่านได้เกือบทั้งหมด ทำให้มองเห็นวัตถุด้านหลังได้อย่างชัดเจน เรียกว่าอะไร?', '["ตัวกลางโปร่งใส","ตัวกลางโปร่งแสง","วัตถุทึบแสง","กระจกเงา"]'::jsonb, 0, 'ตัวกลางโปร่งใส เช่น กระจกใส อากาศ น้ำใส แสงผ่านได้เกือบ 100% ทำให้มองเห็นวัตถุด้านหลังได้ชัดเจน'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] ตัวกลางโปร่งแสง', 'medium', 'mcq', 'สิ่งของในข้อใดจัดเป็น "ตัวกลางโปร่งแสง" (แสงผ่านได้บางส่วน มองเห็นไม่ชัดเจน)?', '["แผ่นแก้วใส","กระดาษไข, กระจกฝ้า, หมอกควัน","แผ่นไม้, แผ่นเหล็ก","ผ้าม่านหนาทึบ"]'::jsonb, 1, 'กระดาษไขและกระจกฝ้า แสงผ่านได้เพียงบางส่วน ทำให้มองเห็นภาพด้านหลังมัวๆ ไม่ชัดเจน'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] วัตถุทึบแสงและการเกิดเงา', 'easy', 'mcq', 'เมื่อแสงส่องกระทบ "วัตถุทึบแสง" จะเกิดสิ่งใดขึ้นด้านหลังของวัตถุ?', '["ภาพสะท้อนหัวกลับ","เงาของวัตถุ","การหักเหเป็นสีรุ้ง","ความสว่างเพิ่มขึ้น"]'::jsonb, 1, 'วัตถุทึบแสงไม่ยอมให้แสงทะลุผ่าน แสงจึงถูกกั้นไว้ ทำให้เกิดเงามืด/เงามัวที่ฉากด้านหลังวัตถุ'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] การเกิดเงา', 'medium', 'mcq', 'ถ้าเลื่อนแหล่งกำเนิดแสงให้ "เข้าใกล้วัตถุมากขึ้น" ขนาดของเงาบนฉากจะเป็นอย่างไร?', '["เงามีขนาดเล็กลง","เงามีขนาดใหญ่ขึ้น","เงาหายไป","ขนาดของเงาเท่าเดิม"]'::jsonb, 1, 'เมื่อแหล่งกำเนิดแสงอยู่ใกล้วัตถุมากขึ้น วัตถุจะบดบังแนวลำแสงเป็นมุมกว้างขึ้น ทำให้เงาบนฉากมีขนาดใหญ่ขึ้น'),
('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] การประยุกต์ใช้ตัวกลางในชีวิตประจำวัน', 'medium', 'mcq', 'ในการสร้างห้องน้ำที่ต้องการแสงสว่างธรรมชาติแต่ต้องการความเป็นส่วนตัว ควรเลือกใช้วัสดุใดทำช่องรับแสง?', '["แผ่นกระจกใส","กระจกฝ้า","แผ่นเหล็กทึบ","ไม้อัด"]'::jsonb, 1, 'กระจกฝ้าเป็นตัวกลางโปร่งแสง ยอมให้แสงแดดส่องผ่านเข้ามาได้ แต่คนภายนอกมองไม่เห็นภาพด้านในชัดเจน'),
('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/1] ศูนย์กลางของระบบสุริยะ', 'easy', 'mcq', 'ดาวดวงใดเป็นศูนย์กลางของระบบสุริยะ และมีดาวเคราะห์โคจรรอบๆ?', '["โลก","ดวงอาทิตย์","ดวงจันทร์","ดาวพฤหัสบดี"]'::jsonb, 1, 'ดวงอาทิตย์เป็นดาวฤกษ์ดวงเดียวที่เป็นศูนย์กลางของระบบสุริยะ มีแรงโน้มถ่วงดึงดูดดาวเคราะห์ทั้ง 8 ดวงไว้'),
('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/1] ดาวเคราะห์ลำดับต่างๆ ในระบบสุริยะ', 'medium', 'mcq', 'ดาวเคราะห์ที่อยู่ "ใกล้ดวงอาทิตย์มากที่สุด" และ "ขนาดใหญ่ที่สุด" ในระบบสุริยะ คือดาวใดตามลำดับ?', '["ดาวพุธ และ ดาวพฤหัสบดี","ดาวศุกร์ และ ดาวเสาร์","โลก และ ดาวอังคาร","ดาวพุธ และ ดาวเสาร์"]'::jsonb, 0, 'ดาวพุธอยู่ใกล้ดวงอาทิตย์ที่สุด ส่วนดาวพฤหัสบดีเป็นดาวเคราะห์ที่มีขนาดใหญ่ที่สุดในระบบสุริยะ'),
('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/1] ดาวเคราะห์วงในและดาวเคราะห์วงนอก', 'medium', 'mcq', 'ดาวเคราะห์ดวงใดที่ได้รับฉายาว่า "ฝาแฝดของโลก" เนื่องจากมีขนาดใกล้เคียงกับโลก?', '["ดาวพุธ","ดาวศุกร์","ดาวอังคาร","ดาวเนปจูน"]'::jsonb, 1, 'ดาวศุกร์มีขนาด มวล และความหนาแน่นใกล้เคียงกับโลกมาก จึงได้ฉายาว่าเป็นฝาแฝดของโลก'),
('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/1] ดาวเคราะห์หินและดาวเคราะห์แก๊ส', 'hard', 'mcq', 'ดาวเคราะห์ในข้อใดจัดเป็น "ดาวเคราะห์หิน" ทั้งหมด?', '["ดาวพุธ, ดาวศุกร์, โลก, ดาวอังคาร","ดาวพฤหัสบดี, ดาวเสาร์, ดาวยูเรนัส","ดาวเนปจูน, ดาวเสาร์, โลก","ดาวอังคาร, ดาวพฤหัสบดี, ดาวพุธ"]'::jsonb, 0, 'ดาวเคราะห์ชั้นใน 4 ดวงแรก (พุธ ศุกร์ โลก อังคาร) เป็นดาวเคราะห์หินที่มีพื้นผิวแข็ง'),
('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/1] ดาวเคราะห์ที่มีวงแหวนโดดเด่น', 'easy', 'mcq', 'ดาวเคราะห์ดวงใดในระบบสุริยะที่มีวงแหวนขนาดใหญ่สวยงาม ชัดเจนที่สุด?', '["ดาวพฤหัสบดี","ดาวเสาร์","ดาวยูเรนัส","ดาวเนปจูน"]'::jsonb, 1, 'ดาวเสาร์มีระบบวงแหวนน้ำแข็งและเศษหินที่กว้างใหญ่ สวยงามและโดดเด่นที่สุด'),
('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/2] การเกิดข้างขึ้น-ข้างแรม', 'medium', 'mcq', 'ปรากฏการณ์ข้างขึ้น-ข้างแรม เกิดจากสาเหตุใด?', '["เงาของโลกบังดวงจันทร์","ดวงจันทร์โคจรรอบโลก ทำให้มุมระหว่างดวงอาทิตย์ โลก และดวงจันทร์เปลี่ยนไป","ดวงอาทิตย์ดับเป็นบางช่วง","ดวงจันทร์หมุนรอบตัวเองเร็วเกินไป"]'::jsonb, 1, 'เกิดจากการที่ดวงจันทร์โคจรรอบโลก ทำให้ส่วนสว่างที่ได้รับแสงจากดวงอาทิตย์หันมายังโลกในมุมที่ต่างกันในแต่ละคืน'),
('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/2] คืนเดือนมืดและคืนวันเพ็ญ', 'easy', 'mcq', 'ในคืน "วันเพ็ญขึ้น 15 ค่ำ" เราจะมองเห็นดวงจันทร์ในลักษณะใด?', '["มองไม่เห็นดวงจันทร์เลย (เดือนมืด)","สว่างเต็มดวงกลมโต","สว่างเพียงครึ่งดวง","เป็นรูปเสี้ยวบางๆ"]'::jsonb, 1, 'วันขึ้น 15 ค่ำ ดวงจันทร์อยู่ตรงข้ามกับดวงอาทิตย์โดยมีโลกอยู่ระหว่างกลาง เราจึงเห็นด้านสว่างของดวงจันทร์เต็มดวง'),
('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/2] การขึ้นและตกของดวงจันทร์', 'medium', 'mcq', 'ดวงจันทร์ปรากฏขึ้นและตกในทิศทางใดของขอบฟ้า?', '["ขึ้นทางทิศตะวันตก ตกทางทิศตะวันออก","ขึ้นทางทิศตะวันออก ตกทางทิศตะวันตก","ขึ้นทางทิศเหนือ ตกทางทิศใต้","ขึ้นและตกไม่แน่นอน"]'::jsonb, 1, 'เนื่องจากโลกหมุนรอบตัวเองจากทิศตะวันตกไปทิศตะวันออก ทำให้เรามองเห็นดวงจันทร์ขึ้นทางทิศตะวันออกและตกทางทิศตะวันตกเช่นเดียวกับดวงอาทิตย์'),
('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/1] การใช้เหตุผลเชิงตรรกะในการแก้ปัญหา', 'easy', 'mcq', 'การแสดงขั้นตอนการแก้ปัญหาโดยการเขียนเป็นข้อความบอกเล่าตามลำดับก่อนหลัง เรียกว่าอะไร?', '["อัลกอริทึม (Algorithm)","การเขียนโปรแกรม","การแก้สมการ","การบักกิ้ง"]'::jsonb, 0, 'อัลกอริทึม คือกระบวนการแก้ปัญหาที่มีลำดับขั้นตอนชัดเจน สามารถปฏิบัติตามได้ผลลัพธ์ที่ถูกต้อง'),
('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/1] การหาข้อผิดพลาดของโปรแกรม (Debugging)', 'medium', 'mcq', 'เมื่อโปรแกรมทำงานผิดพลาดไม่ตรงตามที่คาดหวัง ขั้นตอนการตรวจสอบและแก้ไขข้อผิดพลาดเรียกว่าอะไร?', '["Coding","Debugging","Compiling","Downloading"]'::jsonb, 1, 'Debugging คือการตรวจหาและแก้ไขข้อผิดพลาด (Bug) ภายในโปรแกรมคำสั่ง'),
('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/2] การเขียนโปรแกรมแบบบล็อก (Block Programming / Scratch)', 'easy', 'mcq', 'ในโปรแกรม Scratch หากต้องการให้ตัวละครเดินซ้ำไปเรื่อยๆ ไม่รู้จบ ควรใช้บล็อกคำสั่งใด?', '["if then","forever (วนซ้ำตลอด)","repeat 10","wait 1 sec"]'::jsonb, 1, 'บล็อก "forever" ใช้สำหรับสั่งให้ชุดคำสั่งภายในวนทำงานซ้ำไปเรื่อยๆ อย่างต่อเนื่องไม่มีที่สิ้นสุด'),
('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/2] การทำงานแบบมีเงื่อนไข (Condition)', 'medium', 'mcq', '"ถ้าฝนตก ให้อยู่ในร่ม ถ้าฝนไม่ตก ให้ออกไปเตะฟุตบอล" ข้อความนี้ตรงกับโครงสร้างคำสั่งใดในทางคอมพิวเตอร์?', '["การทำงานแบบลำดับ (Sequence)","การทำงานแบบมีเงื่อนไข (If-Else)","การวนซ้ำแบบไม่จำกัด","การสุ่มค่า"]'::jsonb, 1, 'โครงสร้าง "ถ้า...แล้ว...มิฉะนั้น..." คือโครงสร้างแบบมีเงื่อนไข (If - Else) เพื่อเลือกทำตามสภาวะที่เกิดขึ้นจริง'),
('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/3] การใช้อินเทอร์เน็ตค้นหาความรู้', 'easy', 'mcq', 'โปรแกรมประเภทเว็บเบราว์เซอร์ (Web Browser) ข้อใดที่ใช้สำหรับเปิดดูเว็บไซต์บนอินเทอร์เน็ต?', '["Google Chrome, Microsoft Edge","Microsoft Excel","Adobe Photoshop","Scratch Offline"]'::jsonb, 0, 'Google Chrome, Microsoft Edge, Safari เป็นโปรแกรมเว็บเบราว์เซอร์สำหรับเปิดเข้าสู่เว็บไซต์ต่างๆ'),
('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/3] การใช้คำสำคัญ (Keywords) ในการค้นหา', 'medium', 'mcq', 'หากต้องการค้นหาข้อมูลเกี่ยวกับ "การสังเคราะห์ด้วยแสงของพืชชั้น ป.4" คำค้นหาในข้อใดตรงประเด็นและได้ผลลัพธ์ดีที่สุด?', '["ต้นไม้สีเขียวทำอะไรได้บ้างในโลก","การสังเคราะห์ด้วยแสง พืช ป.4","ทำไมใบไม้จึงเป็นสีเขียวชอบแดด","วิทยาศาสตร์สนุกจัง"]'::jsonb, 1, 'การใช้คำค้นหาที่สั้น กระชับ และตรงประเด็น (Keyword) จะช่วยให้เครื่องมือค้นหาแสดงผลลัพธ์ที่ตรงตามความต้องการได้เร็วที่สุด'),
('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/3] การประเมินความน่าเชื่อถือของข้อมูล', 'hard', 'mcq', 'แหล่งข้อมูลบนอินเทอร์เน็ตในข้อใดมีความน่าเชื่อถือสูงที่สุดในการอ้างอิงรายงานทางวิทยาศาสตร์?', '["โพสต์ในเว็บบอร์ดนิรนามที่ไม่มีคนลงชื่อ","เว็บไซต์ของหน่วยงานราชการหรือมหาวิทยาลัย (เช่น .ac.th, .go.th)","ความเห็นบนโซเชียลมีเดียที่แชร์ต่อๆ กันมา","บล็อกส่วนตัวที่ไม่มีการระบุแหล่งที่มา"]'::jsonb, 1, 'เว็บไซต์ของหน่วยงานรัฐหรือสถาบันการศึกษา (.go.th, .ac.th) มีการตรวจทานข้อมูลโดยผู้เชี่ยวชาญ จึงมีความน่าเชื่อถือสูง'),
('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/4] มารยาทและความปลอดภัยในการใช้อินเทอร์เน็ต', 'easy', 'mcq', 'ข้อใดเป็นการปฏิบัติตัวที่ "ปลอดภัย" ในการใช้อินเทอร์เน็ต?', '["บอกรหัสผ่าน (Password) ให้เพื่อนทุกคนในห้องรู้","ตั้งรหัสผ่านที่คาดเดายาก และไม่เปิดเผยข้อมูลส่วนตัวให้คนแปลกหน้า","นัดพบคนแปลกหน้าที่คุยผ่านเกมออนไลน์ตามลำพัง","โพสต์รูปบัตรประชาชนลงบนอินเทอร์เน็ต"]'::jsonb, 1, 'การรักษาความลับของรหัสผ่านและไม่เปิดเผยข้อมูลส่วนตัวแก่คนแปลกหน้า เป็นวิธีป้องกันภัยคุกคามทางไซเบอร์ที่ถูกต้อง'),
('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/4] การเคารพสิทธิ์และลิขสิทธิ์ของผู้อื่น', 'medium', 'mcq', 'เมื่อนำรูปภาพจากอินเทอร์เน็ตมาใช้ประกอบรายงาน ควรปฏิบัติตนอย่างไรจึงจะถูกต้องตามมารยาท?', '["ลบลายน้ำแล้วอ้างว่าเป็นภาพที่ตนเองวาด","ระบุแหล่งที่มาของภาพเพื่อเป็นการให้เกียรติเจ้าของผลงาน","ไม่ต้องทำอะไรเพราะภาพบนอินเทอร์เน็ตเป็นของทุกคน","นำไปพิมพ์ขายหารายได้พิเศษทันที"]'::jsonb, 1, 'การอ้างอิงแหล่งที่มาของข้อมูลและภาพ (Credit) เป็นการเคารพทรัพย์สินทางปัญญาและมีมารยาททางดิจิทัล'),
('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/4] การกลั่นแกล้งบนโลกออนไลน์ (Cyberbullying)', 'easy', 'mcq', 'พฤติกรรมใดจัดเป็นการกลั่นแกล้งบนโลกออนไลน์ (Cyberbullying) ที่ไม่ควรทำ?', '["การส่งสติกเกอร์ให้กำลังใจเพื่อน","การแชร์ภาพล้อเลียนหรือพิมพ์ข้อความด่าทอประจานเพื่อนในโซเชียล","การตั้งกลุ่มทำงานวิชาวิทยาศาสตร์","การชมเชยผลงานของเพื่อน"]'::jsonb, 1, 'การโพสต์ล้อเลียน ด่าทอ หรือประจานผู้อื่นบนสื่อออนไลน์เป็นการกลั่นแกล้งที่ผิดกฎหมายและสร้างความเสียหายต่อจิตใจผู้อื่น');
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active)
